class Stack {
    struct Node {
        int value;
        Node *next;
    };
    Node *head;
public:
    Stack() : head(@1) {}
    bool empty() const { return @2; }

    void push(int value) {
        Node *node = new Node{value, @3};
        head = @4;
    }
    int top() const {
        if (empty()) throw runtime_error("empty stack");
        return @5; // Read without removing.
    }
    void pop() {
        if (empty()) throw runtime_error("empty stack");
        Node *old = @6;
        head = @7; // Advance BEFORE deleting the old node.
        delete @8;
    }
    @9() {
        while (!empty()) @10;
    }
    // This owner must not share nodes through an accidental shallow copy.
    Stack(const Stack&) = delete;
    Stack& operator=(const Stack&) = delete;
};

int main() {
    Stack s;
    s.push(10);
    s.push(20);
    s.push(30);
    while (!s.empty()) {
        cout << s.@11() << ' ';
        s.pop();
    }
    cout << '\n'; // Expected order: 30 20 10
}

