#include <iostream>
#include <stdexcept>
using namespace std;

class Queue {
    struct Node { int value; Node *next; };
    Node *frontNode;
    Node *rearNode;
public:
    Queue() : frontNode(nullptr), rearNode(nullptr) {}
    bool empty() const { return @1; }

    void enqueue(int value) {
        Node *node = new Node{value, @2};
        if (empty()) {
            frontNode = @3; // First node is both front and rear.
        } else {
            rearNode->next = @4;
        }
        rearNode = @5;
    }
    int front() const {
        if (empty()) throw runtime_error("empty queue");
        return @6;
    }
    void dequeue() {
        if (empty()) throw runtime_error("empty queue");
        Node *old = @7;
        frontNode = @8;
        if (frontNode == nullptr) {
            rearNode = @9; // No dangling rear after removing last node.
        }
        delete @10;
    }
    ~Queue() {
        while (!empty()) @11;
    }
    Queue(const Queue&) = delete;
    Queue& operator=(const Queue&) = delete;
};

int main() {
    Queue q;
    q.enqueue(10);
    q.enqueue(20);
    q.enqueue(30);
    while (!q.empty()) {
        cout << q.@12() << ' ';
        q.dequeue();
    }
    cout << '\n'; // Expected order: 10 20 30
    q.enqueue(40); // Reuse the queue after it becomes empty.
    cout << q.front() << '\n';
}

